// C: Guaranteed Deallocation Pattern
void safe_alloc_c() {
    int* data = NULL;
    data = (int*)malloc(sizeof(int) * 10);
    if (!data) return;
    // Processing...
    free(data);
}

// C++: Manual Leak Example
void leak_cpp() {
    std::string* s = new std::string("Leak Me");
    // Leak occurs: delete s is missing
}

// C++: RAII (Resource Acquisition Is Initialization)
class Resource {
    int* ptr;
public:
    Resource(int val) : ptr(new int(val)) {}
    ~Resource() { delete ptr; } // Guarantee cleanup
};

// C++: Smart Pointer Usage (Standard Practice)
void safe_alloc_cpp() {
    // Automatically calls delete[]
    std::unique_ptr<char[]> buffer =
        std::make_unique<char[]>(1024);
}
